const validURL=s=>!s||/^https?:\/\/[^\s<>"']+$/i.test(s);
function valid(raw){if(!raw||raw.version!==3||!raw.settings||typeof raw.settings!=='object')return false;const s=raw.settings;
 if(typeof s.schoolName!=='string'||s.schoolName.length>70||!['meadow','peach','lilac','blue','sand','custom'].includes(s.theme)||!/^#[0-9a-f]{6}$/i.test(s.customColor)||!['sans','serif','rounded'].includes(s.font)||!['compact','comfortable','spacious'].includes(s.density)||!['soft','outlined'].includes(s.cards)||!['normal','high'].includes(s.contrast)||!['USD','GBP','EUR','CAD','AUD','PKR'].includes(s.currency)||!dateOK(s.yearStart)||!dateOK(s.yearEnd)||s.yearEnd<s.yearStart||!Number.isSafeInteger(s.targetDays)||s.targetDays<0||s.targetDays>3660||!Number.isSafeInteger(s.targetHours)||s.targetHours<0||s.targetHours>100000)return false;
 if(!s.weights||!['Practice','Quiz','Test'].every(k=>Number.isSafeInteger(s.weights[k])&&s.weights[k]>=0&&s.weights[k]<=100)||Object.values(s.weights).reduce((a,b)=>a+b,0)!==100)return false;
 const ids=new Set();for(const k of kinds){if(!Array.isArray(raw[k])||raw[k].length>10000)return false;for(const r of raw[k]){if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id))return false;ids.add(r.id);for(const [key,,type,required] of fields[k]){const v=r[key];if(required&&(v==null||v===''))return false;if(v==null||v==='')continue;if(['int','score','money'].includes(type)){if(!Number.isSafeInteger(v)||v<0||v>100000000000)return false}else if(typeof v!=='string'||v.length>3000||type==='date'&&!dateOK(v)||type==='time'&&!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(v)||type==='url'&&!validURL(v)||type==='color'&&!/^#[0-9a-f]{6}$/i.test(v))return false}
 if(['lessons','assessments'].includes(k)&&((r.score==null)!==(r.maxScore==null)||r.score!=null&&(r.maxScore<=0||r.score>r.maxScore)))return false;
 if(k==='curricula'&&r.unitsDone>r.unitsTotal||['goals','projects'].includes(k)&&r.progress>r.target||k==='reading'&&r.rating!=null&&r.rating!==''&&r.rating>5||k==='yearEvents'&&r.end<r.date)return false}}
 return true}
