let dbPromise;function db(){return dbPromise??=new Promise((resolve,reject)=>{const q=indexedDB.open(DB,1);q.onupgradeneeded=()=>q.result.createObjectStore(STORE);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function readState(){const d=await db();return new Promise((resolve,reject)=>{const q=d.transaction(STORE,'readonly').objectStore(STORE).get(KEY);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function readLegacyState(){return new Promise((resolve,reject)=>{const q=indexedDB.open('pennyharbor-open-meadow');q.onsuccess=()=>{const old=q.result;if(!old.objectStoreNames.contains(STORE)){old.close();resolve(undefined);return}const get=old.transaction(STORE,'readonly').objectStore(STORE).get(KEY);get.onsuccess=()=>{old.close();resolve(get.result)};get.onerror=()=>{old.close();reject(get.error)}};q.onerror=()=>reject(q.error)})}
async function writeState(value){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction(STORE,'readwrite');tx.objectStore(STORE).put(value,KEY);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
let menuFocus=null;let data=blank(),view='dashboard',selected=today(),planMode='week',reportMode='card',search='',filterStudent='',reportStudent='',modal=null,previousFocus=null,writeQueue=Promise.resolve();
function save(){const snapshot=structuredClone(data),status=$('#saveStatus');if(status)status.textContent='Saving…';const task=writeQueue.catch(()=>{}).then(()=>writeState(snapshot));writeQueue=task;task.then(()=>{if(task===writeQueue){const s=$('#saveStatus');if(s)s.textContent='Saved on this device'}},()=>{const s=$('#saveStatus');if(s)s.textContent='Could not save. Export a backup now.'});task.catch(()=>{});return task}
async function initialize(){try{let saved=await readState();if(saved===undefined){saved=await readLegacyState();if(saved===undefined)saved=DEMO?sample():blank()}const upgraded=upgrade(saved);if(!valid(upgraded))throw Error('Saved data did not pass validation. Nothing was erased.');data=upgraded;await writeState(upgraded);shell()}catch(e){app.innerHTML=`<div class="error-screen" role="alert"><h1>Open Meadow could not open</h1><p>${esc(e.message)}</p><p>Check browser storage permissions or open in a normal browser window. Your existing records were not cleared.</p></div>`}}
const student=id=>data.students.find(r=>r.id===id)?.name||'All students',subject=id=>data.subjects.find(r=>r.id===id)?.name||'General';
const sum=(a,key)=>a.reduce((n,r)=>n+(r[key]||0),0),inYear=d=>d>=data.settings.yearStart&&d<=data.settings.yearEnd;
function average(studentId,subjectId,yearOnly=false){const rows=[...data.lessons,...data.assessments].filter(r=>r.studentId===studentId&&r.subjectId===subjectId&&r.score!=null&&r.maxScore>0&&(!yearOnly||inYear(r.date))),cats=['Practice','Quiz','Test'];let numerator=0,weight=0;for(const c of cats){const a=rows.filter(r=>r.category===c);if(a.length&&data.settings.weights[c]){numerator+=sum(a,'score')/sum(a,'maxScore')*data.settings.weights[c];weight+=data.settings.weights[c]}}return weight?Math.round(numerator/weight*100):null}
const grade=n=>n==null?'—':n>=90?'A':n>=80?'B':n>=70?'C':n>=60?'D':'F';
function readableAccent(hex){let [r,g,b]=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));const lum=()=>[r,g,b].map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((a,v,i)=>a+v*[.2126,.7152,.0722][i],0);while(lum()>.17){r=Math.round(r*.9);g=Math.round(g*.9);b=Math.round(b*.9)}return '#'+[r,g,b].map(v=>v.toString(16).padStart(2,'0')).join('')}
function apply(){const s=data.settings,root=document.documentElement;for(const k of ['theme','font','density','cards','contrast'])root.dataset[k]=s[k];root.style.setProperty('--custom',readableAccent(s.customColor));root.style.setProperty('--custom-soft',s.customColor+'24');document.title=`${s.schoolName||'Open Meadow'} · Open Meadow`}
function shell(){app.innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-icon">✿</span><span><strong>Open Meadow</strong><small>BY HARBORNESTDIGITAL</small></span></div><p class="side-note">A calmer place for every learner.</p><nav aria-label="Planner sections">${nav.map(([v,l,i])=>`<button class="nav-item" data-view="${v}"><span aria-hidden="true">${i}</span>${l}</button>`).join('')}</nav><p class="side-bottom">Plan · learn · remember</p></aside><div class="main-shell"><header class="topbar"><span class="top-brand">✿ Open Meadow</span><span id="saveStatus" role="status">Saved on this device</span></header>${DEMO?'<div class="demo-banner" role="status">Sample demo · Try the planner freely. Restore sample records in Customize.</div>':''}<main id="main" tabindex="-1"></main></div><nav class="mobile-nav" aria-label="Primary planner sections">${nav.filter(([v])=>['dashboard','planner','calendar','progress'].includes(v)).map(([v,l,i])=>`<button class="nav-item" data-view="${v}"><span aria-hidden="true">${i}</span><small>${l}</small></button>`).join('')}<button class="nav-item" data-more aria-label="More planner sections"><span aria-hidden="true">☰</span><small>More</small></button></nav>`;apply();render()}
