const selectStudents=(value='',attr='data-filter-student')=>`<label class="compact-select">Student <select ${attr}><option value="">All students</option>${data.students.map(r=>`<option value="${esc(r.id)}" ${value===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label>`;
const filtered=arr=>filterStudent?arr.filter(r=>r.studentId===filterStudent):arr;
function dashboard(){const t=today(),up=sorted(data.lessons.filter(r=>r.date>=t&&r.status!=='Done')).slice(0,4),yearAttendance=data.attendance.filter(r=>inYear(r.date)&&r.status==='Present'),hours=sum(yearAttendance,'minutes')/60,graded=[...data.lessons,...data.assessments].filter(r=>r.score!=null).length,done=data.lessons.filter(r=>r.status==='Done').length,late=data.lessons.filter(r=>r.status!=='Done'&&r.date<t).length;return `<div class="hero"><div><span class="eyebrow">YOUR HOMESCHOOL, IN FOCUS</span><h2>Make room for a good learning day.</h2><p>One place for lessons, records and the little victories.</p>${button('lessons','Plan a lesson')}</div><span aria-hidden="true">✿</span></div><div class="stats"><div class="stat"><small>Lessons completed</small><strong>${done}</strong><span>Across your records</span></div><div class="stat"><small>Days present</small><strong>${schoolDays()}</strong><span>This school year</span></div><div class="stat"><small>Instructional hours</small><strong>${hours.toFixed(1)}</strong><span>Logged in attendance</span></div><div class="stat"><small>Past due</small><strong>${late}</strong><span>Open assignments & lessons</span></div></div><div class="two-col">${card('Coming up',rows('lessons',up,r=>`<strong>${esc(r.title)}</strong><small>${dateLabel(r.date)} · ${esc(student(r.studentId))} · ${esc(subject(r.subjectId))}</small>`))}${card('Your learners',data.students.length?`<div class="student-cards">${data.students.map(r=>`<div><span class="avatar">${esc(r.name.slice(0,1))}</span><strong>${esc(r.name)}</strong><small>${esc(r.level||'Learner')}</small></div>`).join('')}</div><button class="button secondary" data-view="students">Manage students</button>`:empty('students'))}</div>${late?card('Needs attention · past due',rows('lessons',sorted(data.lessons.filter(r=>r.status!=='Done'&&r.date<t)).slice(0,8),r=>`<strong>${esc(r.title)}</strong>${pill('Past due','late')}<small>${dateLabel(r.date)} · ${esc(student(r.studentId))}</small>`)):''}${card('Progress at a glance',`<div class="stat-rings"><div class="ring" style="--pct:${Math.min(100,Math.round(schoolDays()/Math.max(1,data.settings.targetDays)*100))}"><strong>${Math.min(100,Math.round(schoolDays()/Math.max(1,data.settings.targetDays)*100))}%</strong><small>Days target</small></div><div class="ring" style="--pct:${Math.min(100,Math.round(hours/Math.max(1,data.settings.targetHours)*100))}"><strong>${Math.min(100,Math.round(hours/Math.max(1,data.settings.targetHours)*100))}%</strong><small>Hours target</small></div><div class="ring" style="--pct:${data.lessons.length?Math.round(done/data.lessons.length*100):0}"><strong>${data.lessons.length?Math.round(done/data.lessons.length*100):0}%</strong><small>Lessons done</small></div></div><p class="help">${graded} graded entries · charts reflect saved records and your planning targets.</p>`)}${card('A quick start',`<div class="quick-grid"><button data-add="students">01 <strong>Add a learner</strong><span>Set up each child.</span></button><button data-add="subjects">02 <strong>Add subjects</strong><span>Give lessons a home.</span></button><button data-add="attendance">03 <strong>Log today</strong><span>Track days and hours.</span></button></div>`,'soft-card')}`}
function dateToolbar(){return `<div class="toolbar"><button class="icon-button" data-shift="${planMode==='month'?-1:planMode==='week'?-7:-1}" aria-label="Previous period">‹</button><strong>${planMode==='month'?new Date(selected+'T12:00:00Z').toLocaleDateString(undefined,{month:'long',year:'numeric',timeZone:'UTC'}):planMode==='week'?'Week of '+dateLabel(weekStart(selected)):dateLabel(selected)}</strong><button class="icon-button" data-shift="${planMode==='month'?1:planMode==='week'?7:1}" aria-label="Next period">›</button><button class="button secondary" data-today>Today</button><div class="segments">${['day','week','month'].map(m=>`<button data-mode="${m}" class="${planMode===m?'active':''}" aria-pressed="${planMode===m}">${m}</button>`).join('')}</div></div>`}
function planner(){let start=planMode==='day'?selected:planMode==='week'?weekStart(selected):selected.slice(0,7)+'-01',end=planMode==='day'?selected:planMode==='week'?addDays(start,6):dateFrom(Number(start.slice(0,4)),Number(start.slice(5,7)),0),a=sorted(filtered(data.lessons).filter(r=>r.date>=start&&r.date<=end));return `${dateToolbar()}<div class="section-bar">${selectStudents()}${button('lessons')}</div>${card('Lessons & assignments',rows('lessons',a,r=>`<div class="record-top"><strong>${esc(r.title)}</strong>${pill(r.status,r.status==='Done'?'done':'')}</div><small>${dateLabel(r.date)} · ${esc(student(r.studentId))} · ${esc(subject(r.subjectId))} · ${r.minutes||0} min</small>${r.objective?`<p>${esc(r.objective)}</p>`:''}${r.score!=null?`<small>Grade: ${r.score}/${r.maxScore} (${Math.round(r.score/r.maxScore*100)}%) · ${esc(r.category)}</small>`:''}`))}<p class="help">Enter a score when editing a lesson. It appears in Gradebook automatically, without a duplicate grade entry.</p>`}
function calendar(){const m=selected.slice(0,7),[y,mo]=m.split('-').map(Number),lead=(new Date(Date.UTC(y,mo-1,1)).getUTCDay()+6)%7,days=new Date(Date.UTC(y,mo,0)).getUTCDate(),count=Math.ceil((lead+days)/7)*7;return `<div class="toolbar"><button class="icon-button" data-month="-1" aria-label="Previous month">‹</button><strong>${new Date(selected+'T12:00:00Z').toLocaleDateString(undefined,{month:'long',year:'numeric',timeZone:'UTC'})}</strong><button class="icon-button" data-month="1" aria-label="Next month">›</button><button class="button secondary" data-today>Today</button></div>${card('Family learning calendar',`<div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<b>${d}</b>`).join('')}${Array.from({length:count},(_,i)=>{const n=i-lead+1;if(n<1||n>days)return '<span class="cal-empty"></span>';const date=dateFrom(y,mo-1,n),a=data.lessons.filter(r=>r.date===date),b=data.attendance.filter(r=>r.date===date&&r.status==='Present'),ev=data.events.filter(r=>r.date===date),tr=data.trips.filter(r=>r.date===date),tests=data.assessments.filter(r=>r.date===date),breaks=data.yearEvents.filter(r=>r.date<=date&&r.end>=date);return `<button class="cal-day ${date===today()?'today':''}" data-date="${date}" aria-label="${dateLabel(date)}: ${a.length} lessons, ${tests.length} assessments, ${ev.length} events, ${tr.length} trips, ${breaks.length} breaks"><strong>${n}</strong><small>${a.length?a.length+' lessons':''}</small><span class="cal-dots">${a.length?'<i class="lesson-dot"></i>':''}${tests.length?'<i class="test-dot"></i>':''}${ev.length?'<i class="event-dot"></i>':''}${tr.length?'<i class="trip-dot"></i>':''}${breaks.length?'<i class="break-dot"></i>':''}</span><small>${ev[0]?esc(ev[0].title):breaks[0]?esc(breaks[0].title):''}</small></button>`}).join('')}</div><p class="help">Color key: <span class="key lesson-dot"></span> lessons <span class="key test-dot"></span> tests <span class="key event-dot"></span> family <span class="key trip-dot"></span> trips <span class="key break-dot"></span> breaks. Select a date to plan its lessons.</p>`)}<div class="section-bar">${button('lessons')}${button('events','Add family event')}${button('yearEvents','Add break')}</div>`}
function studentsView(){return `<div class="section-bar">${button('students')}${button('subjects')}</div><div class="two-col">${card('Student profiles',rows('students',data.students,r=>`<strong>${esc(r.name)}</strong><small>${esc(r.level||'Learner')} · ${esc(r.style||'Add learning preferences')}</small>${r.support?`<p>Support: ${esc(r.support)}</p>`:''}`))}${card('Subject plans',rows('subjects',data.subjects,r=>`<span class="subject-dot" style="background:${esc(r.color||'#74a898')}"></span><strong>${esc(r.name)}</strong>${r.units?`<p>Units: ${esc(r.units)}</p>`:''}${r.objective?`<p>Objectives: ${esc(r.objective)}</p>`:''}${r.resources?`<p>Resources: ${esc(r.resources)}</p>`:''}`))}</div>`}
function attendanceView(){const a=sorted(filtered(data.attendance),'date').reverse(),yr=a.filter(r=>inYear(r.date)),days=new Set(yr.filter(r=>r.status==='Present').map(r=>r.date)).size,hours=sum(yr.filter(r=>r.status==='Present'),'minutes')/60;return `<div class="section-bar">${selectStudents()}${button('attendance','Log attendance')}</div><div class="stats three"><div class="stat"><small>Days present</small><strong>${days}</strong><span>Unique school dates</span></div><div class="stat"><small>Hours logged</small><strong>${hours.toFixed(1)}</strong><span>Present entries only</span></div><div class="stat"><small>Your targets</small><strong>${data.settings.targetDays} days</strong><span>${data.settings.targetHours} hours · editable</span></div></div>${card('Attendance log',rows('attendance',a,r=>`<strong>${esc(student(r.studentId))}</strong>${pill(r.status)}<small>${dateLabel(r.date)} · ${r.minutes||0} instructional minutes${r.note?' · '+esc(r.note):''}</small>`))}<p class="help">Targets are for your own planning. Rules vary by location; verify requirements with your local authority.</p>`}
function gradebook(){const graded=filtered([...data.lessons,...data.assessments]).filter(r=>r.score!=null),students=filterStudent?data.students.filter(r=>r.id===filterStudent):data.students;return `<div class="section-bar">${selectStudents()}${button('lessons','Add graded lesson')}${button('assessments','Add assessment')}</div>${card('Subject averages',students.length?`<div class="grade-grid">${students.flatMap(st=>data.subjects.map(sub=>{const n=average(st.id,sub.id);return `<div class="grade-tile"><small>${esc(st.name)} · ${esc(sub.name)}</small><strong>${n==null?'—':n+'%'}</strong><span>${n==null?'No scores yet':grade(n)+' · weighted average'}</span>${progress(n||0,100)}</div>`})).join('')}</div>`:empty('students'))}${card('Graded lessons & assessments',graded.length?`<div class="records">${sorted(graded).reverse().map(r=>`<article class="record"><div class="record-body"><strong>${esc(r.title)}</strong><small>${esc(student(r.studentId))} · ${esc(subject(r.subjectId))} · ${dateLabel(r.date)}${r.kind?' · '+esc(r.kind):''}</small><span class="grade-chip">${r.score}/${r.maxScore} · ${Math.round(r.score/r.maxScore*100)}%</span></div>${actions(r.kind?'assessments':'lessons',r)}</article>`).join('')}</div>`:empty('lessons'))}<p class="help">Category weights: Practice ${data.settings.weights.Practice}%, Quiz ${data.settings.weights.Quiz}%, Test ${data.settings.weights.Test}%. Available categories are reweighted when some have no scores. Edit weights in Customize.</p>`}
function curriculum(){return `<div class="section-bar">${selectStudents()}${button('curricula','Add curriculum')}</div>${card('Courses & materials',rows('curricula',filtered(data.curricula),r=>`<strong>${esc(r.title)}</strong><small>${esc(student(r.studentId))} · ${esc(subject(r.subjectId))} · ${esc(r.provider||'Own materials')} · ${money(r.cost||0)}</small>${progress(r.unitsDone,r.unitsTotal)}<small>${r.unitsDone}/${r.unitsTotal} units complete · ${r.unitsTotal?Math.round(r.unitsDone/r.unitsTotal*100):0}%</small>`))}`}
function readingView(){const a=filtered(data.reading),mins=sum(a,'minutes'),finished=a.filter(r=>r.status==='Finished').length;return `<div class="section-bar">${selectStudents()}${button('reading','Log reading')}</div><div class="stats two"><div class="stat"><small>Reading minutes</small><strong>${mins}</strong></div><div class="stat"><small>Finished entries</small><strong>${finished}</strong></div></div>${card('Reading log & challenges',rows('reading',sorted(a).reverse(),r=>`<strong>${esc(r.title)}</strong>${pill(r.status)}<small>${esc(student(r.studentId))} · ${esc(r.author||'Author not set')} · ${dateLabel(r.date)} · ${r.minutes||0} min${r.rating?' · '+r.rating+'/5 stars':''}</small>${r.challenge?`<p>Challenge: ${esc(r.challenge)}</p>`:''}${r.note?`<p>Review: ${esc(r.note)}</p>`:''}`))}`}
function goalsView(){return `<div class="section-bar">${selectStudents()}${button('goals','Add learning goal')}</div>${card('Annual, quarterly & monthly goals',rows('goals',filtered(data.goals),r=>`<strong>${esc(r.title)}</strong>${pill(r.period||'Annual')}<small>${esc(student(r.studentId))} · ${esc(subject(r.subjectId))}${r.due?' · Due '+dateLabel(r.due):''}</small>${progress(r.progress,r.target)}<small>${r.progress}/${r.target} units complete</small>${r.milestone?`<p>Next milestone: ${esc(r.milestone)}</p>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}`))}`}
function enrichment(){return `<div class="section-bar">${button('trips','Add field trip')}${button('activities','Add activity')}${button('chores','Add chore / skill')}${button('portfolio','Add work sample')}</div><div class="two-col">${card('Field trips',rows('trips',sorted(data.trips),r=>`<strong>${esc(r.title)}</strong><small>${dateLabel(r.date)} · ${esc(r.place||'Destination')} · ${money(r.cost||0)}</small><p>${esc(r.objective||'')}</p>${r.permission?`<small>Permission: ${esc(r.permission)}</small>`:''}${r.followUp?`<p>Follow-up: ${esc(r.followUp)}</p>`:''}`))}${card('Activities & volunteer hours',rows('activities',sorted(filtered(data.activities)),r=>`<strong>${esc(r.title)}</strong>${pill(r.category)}<small>${esc(student(r.studentId))} · ${dateLabel(r.date)} · ${r.minutes||0} min</small>`))}${card('Chores & life skills',rows('chores',sorted(filtered(data.chores)),r=>`<strong>${esc(r.title)}</strong>${pill(r.status)}<small>${esc(student(r.studentId))} · ${dateLabel(r.date)} · ${esc(r.category)}</small>${r.milestone?`<p>Milestone: ${esc(r.milestone)}</p>`:''}`))}${card('Portfolio index',rows('portfolio',sorted(filtered(data.portfolio)).reverse(),r=>`<strong>${esc(r.title)}</strong><small>${esc(student(r.studentId))} · ${esc(r.type)} · ${dateLabel(r.date)}</small><p>${esc(r.description||'')}</p>${r.link?`<a href="${esc(r.link)}" target="_blank" rel="noopener noreferrer">Open linked file</a>`:''}${r.attachmentData?`<a href="${esc(r.attachmentData)}" download="${esc(r.attachmentName)}">Download attached file</a>`:''}`))}</div><p class="help">Portfolio records can include a small image or PDF attachment stored locally with your browser data and included in JSON backups. Keep backups safe; files are never sent to HarborNestDigital.</p>`}
function budget(){const spent=sum(data.expenses,'amount')+sum(data.curricula,'cost')+sum(data.trips,'cost'),flagged=sum(data.expenses.filter(r=>r.taxTag==='Review for taxes'),'amount');return `<div class="section-bar">${button('expenses','Add expense')}${button('curricula','Add curriculum')}${button('trips','Add trip')}</div><div class="stats three"><div class="stat"><small>Recorded purchases</small><strong>${money(sum(data.expenses,'amount'))}</strong></div><div class="stat"><small>Curriculum costs</small><strong>${money(sum(data.curricula,'cost'))}</strong></div><div class="stat"><small>Total with trips</small><strong>${money(spent)}</strong></div></div>${card('Purchases & review tags',rows('expenses',sorted(data.expenses).reverse(),r=>`<strong>${esc(r.title)}</strong>${pill(r.category)}${r.taxTag==='Review for taxes'?pill(r.taxTag):''}<small>${dateLabel(r.date)} · ${money(r.amount)}</small>`))}<p class="help">${money(flagged)} flagged for your own tax review. Tags do not determine deductibility. Currency settings change formatting only, not saved amounts.</p>`}
function reports(){const sid=reportStudent||data.students[0]?.id||'',a=data.attendance.filter(r=>r.studentId===sid&&inYear(r.date)),present=a.filter(r=>r.status==='Present'),days=new Set(present.map(r=>r.date)).size,hours=sum(present,'minutes')/60,lessons=data.lessons.filter(r=>r.studentId===sid&&inYear(r.date)),done=lessons.filter(r=>r.status==='Done').length,reading=sum(data.reading.filter(r=>r.studentId===sid&&inYear(r.date)),'minutes'),goals=data.goals.filter(r=>r.studentId===sid);const comments=data.reportComments.filter(r=>r.studentId===sid).sort((a,b)=>b.date.localeCompare(a.date)),header=`<div class="report-title"><div><span class="eyebrow">OPEN MEADOW · ${reportMode.toUpperCase()} REPORT</span><h2>${esc(student(sid))}</h2><p>${esc(data.settings.schoolName)} · ${dateLabel(data.settings.yearStart)} to ${dateLabel(data.settings.yearEnd)}</p></div><span aria-hidden="true">✿</span></div>`;const metrics=`<div class="report-metrics"><div><small>Present days</small><strong>${days}</strong><span>of ${data.settings.targetDays} target</span></div><div><small>Instructional hours</small><strong>${hours.toFixed(1)}</strong><span>of ${data.settings.targetHours} target</span></div><div><small>Lessons completed</small><strong>${done}/${lessons.length}</strong></div><div><small>Reading</small><strong>${reading} min</strong></div></div>`;const table=`<h3>Subject progress</h3><div class="report-table"><div class="report-row head"><span>Subject</span><span>Graded work</span><span>Average</span><span>Letter</span></div>${data.subjects.map(sub=>{const n=average(sid,sub.id,true),count=[...lessons,...data.assessments.filter(r=>r.studentId===sid&&inYear(r.date))].filter(r=>r.subjectId===sub.id&&r.score!=null).length;return `<div class="report-row"><span>${esc(sub.name)}</span><span>${count}</span><span>${n==null?'—':n+'%'}</span><span>${grade(n)}</span></div>`}).join('')}</div>`;let body='';if(reportMode==='attendance')body=`${metrics}<h3>Attendance dates</h3><div class="report-table"><div class="report-row head"><span>Date</span><span>Status</span><span>Minutes</span><span>Notes</span></div>${sorted(a).map(r=>`<div class="report-row"><span>${dateLabel(r.date)}</span><span>${esc(r.status)}</span><span>${r.minutes||0}</span><span>${esc(r.note||'—')}</span></div>`).join('')}</div>`;else if(reportMode==='transcript')body=`<p class="help">Unofficial record summary for the selected school year. Review all entries and requirements before sharing.</p>${table}<h3>Courses & curriculum</h3>${data.curricula.filter(r=>r.studentId===sid).map(r=>`<p>${esc(r.title)} · ${esc(subject(r.subjectId))} · ${r.unitsDone}/${r.unitsTotal} units</p>`).join('')||'<p>No courses recorded.</p>'}`;else if(reportMode==='progress')body=`${metrics}${table}<h3>Learning goals</h3>${goals.map(r=>`${valueBar(r.title,r.progress,r.target)}`).join('')||'<p>No goals recorded.</p>'}<h3>Projects & achievements</h3><p>${data.projects.filter(r=>r.studentId===sid).length} projects · ${data.achievements.filter(r=>r.studentId===sid).length} achievements logged</p>`;else body=`${metrics}${table}<h3>Goals</h3>${goals.map(r=>`<p>${esc(r.title)} · ${r.progress}/${r.target}</p>`).join('')||'<p>No goals recorded.</p>'}<div class="report-comment"><h3>Teacher comments</h3>${comments[0]?`<p>${esc(comments[0].body)}</p><small>${dateLabel(comments[0].date)}</small>`:'<div class="writing-lines"></div>'}</div>`;return `<div class="section-bar"><label class="compact-select">Report for <select data-report-student>${data.students.map(r=>`<option value="${esc(r.id)}" ${sid===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><button class="button primary" data-add="reportComments" data-add-student="${esc(sid)}">+ Add comment</button><button class="button secondary" data-print>Print / Save as PDF</button></div><div class="report-modes" aria-label="Report type">${[['card','Report card'],['transcript','Unofficial transcript'],['attendance','Attendance'],['progress','Progress']].map(([k,l])=>`<button data-report-mode="${k}" class="${reportMode===k?'active':''}" aria-pressed="${reportMode===k}">${l}</button>`).join('')}</div><div class="report-sheet">${sid?header+body:empty('students')}</div><p class="help">Reports summarize records you entered. They are not certified transcripts or legal compliance documents.</p>`}
function library(){return `<div class="section-bar">${button('notes','Add note')}${button('resources','Add resource')}</div><div class="two-col">${card('Teaching notes & journal',rows('notes',sorted(data.notes).reverse(),r=>`<strong>${esc(r.title)}</strong><small>${dateLabel(r.date)} · ${esc(student(r.studentId))}</small><p>${esc(r.body)}</p>`))}${card('Educational resources',rows('resources',data.resources,r=>`<strong>${esc(r.title)}</strong>${pill(r.kind||'Website')}<small>${esc(subject(r.subjectId))}</small><p>${esc(r.note||'')}</p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open resource ↗</a>`))}</div>`}
function pref(k,label,values){return `<label class="field">${label}<select data-setting="${k}">${values.map(([v,t])=>`<option value="${v}" ${data.settings[k]===v?'selected':''}>${t}</option>`).join('')}</select></label>`}
function settings(){const s=data.settings;return `<div class="two-col">${card('Your learning space',`<label class="field">Homeschool name<input data-setting="schoolName" maxlength="70" value="${esc(s.schoolName)}"></label><div class="settings-grid"><label class="field">School year starts<input data-setting="yearStart" type="date" value="${s.yearStart}"></label><label class="field">School year ends<input data-setting="yearEnd" type="date" value="${s.yearEnd}"></label><label class="field">Target days<input data-setting="targetDays" type="number" min="0" max="3660" value="${s.targetDays}"></label><label class="field">Target hours<input data-setting="targetHours" type="number" min="0" max="100000" value="${s.targetHours}"></label></div><p class="help">Targets are personal planning aids; they do not determine compliance with local law.</p><h3>Grade category weights</h3><div class="settings-grid">${['Practice','Quiz','Test'].map(k=>`<label class="field">${k} %<input type="number" min="0" max="100" data-weight="${k}" value="${s.weights[k]}"></label>`).join('')}</div><button class="button secondary" data-save-weights>Save weights (total 100%)</button>`)}${card('Appearance & comfort',`<h3>Light color themes</h3><div class="theme-grid">${[['meadow','Meadow'],['peach','Sunrise'],['lilac','Lilac'],['blue','Sky'],['sand','Oat'],['custom','My color']].map(([k,l])=>`<button data-theme="${k}" class="theme-option ${s.theme===k?'selected':''}" aria-pressed="${s.theme===k}"><span class="theme-swatch ${k}"></span>${l}</button>`).join('')}</div><label class="field">Choose your accent<input data-setting="customColor" type="color" value="${s.customColor}"></label><div class="settings-grid">${pref('font','Font',[['sans','Clean sans'],['serif','Classic serif'],['rounded','Soft rounded']])}${pref('density','Spacing',[['compact','Compact'],['comfortable','Comfortable'],['spacious','Spacious']])}${pref('cards','Card style',[['soft','Soft'],['outlined','Outlined']])}${pref('contrast','Readability',[['normal','Standard'],['high','Higher contrast']])}${pref('currency','Currency display',[['USD','USD'],['GBP','GBP'],['EUR','EUR'],['CAD','CAD'],['AUD','AUD'],['PKR','PKR']])}</div><button class="button secondary" data-reset-appearance>Restore default appearance</button>`)}${card('Backup & records',`<p>These records live in this browser on this device. Download a backup before changing devices or clearing browser data.</p><div class="settings-actions"><button class="button primary" data-backup>Download JSON backup</button><button class="button secondary" data-import>Restore backup</button><button class="button secondary" data-export-csv>Export lessons CSV</button><button class="button secondary" data-print>Print this page</button><button class="button danger-button" data-clear>Clear all records</button>${DEMO?'<button class="button secondary" data-reset-demo>Reset sample data</button>':''}</div><p class="help">No account or automatic sync. To move records, export on the old device and import on the new one.</p>`,'full')}</div>`}
const valueBar=(label,current,target)=>`<div class="metric-line"><div><strong>${esc(label)}</strong><span>${current}${target?' / '+target:''}</span></div>${progress(current,target||Math.max(1,current))}</div>`;
const schoolDays=(sid='')=>new Set(data.attendance.filter(r=>(!sid||r.studentId===sid)&&inYear(r.date)&&r.status==='Present').map(r=>r.date)).size;
const schoolHours=(sid='')=>sum(data.attendance.filter(r=>(!sid||r.studentId===sid)&&inYear(r.date)&&r.status==='Present'),'minutes')/60;
function progressView(){const sid=reportStudent||data.students[0]?.id||'',st=data.students.find(r=>r.id===sid);return `<div class="section-bar"><label class="compact-select">Student <select data-report-student>${data.students.map(r=>`<option value="${esc(r.id)}" ${sid===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label></div>${st?`${card('Subject-by-subject progress',`<div class="grade-grid">${data.subjects.map(sub=>{const n=average(sid,sub.id),done=data.lessons.filter(r=>r.studentId===sid&&r.subjectId===sub.id&&r.status==='Done').length,total=data.lessons.filter(r=>r.studentId===sid&&r.subjectId===sub.id).length;return `<div class="grade-tile"><small>${esc(sub.name)}</small><strong>${n==null?'—':n+'%'}</strong><span>${done}/${total} lessons complete</span>${progress(done,total||1)}</div>`}).join('')}</div>`)}<div class="two-col">${card('Year targets',`${valueBar('Attendance days',schoolDays(sid),data.settings.targetDays)}${valueBar('Instructional hours',schoolHours(sid).toFixed(1),data.settings.targetHours)}`)}${card('Learning goals',data.goals.filter(r=>r.studentId===sid).map(r=>valueBar(r.title,r.progress,r.target)).join('')||'<p>No goals yet.</p>')}</div>`:empty('students')}`}
function family(){const start=selected.slice(0,7)+'-01',end=dateFrom(Number(start.slice(0,4)),Number(start.slice(5,7)),0),events=sorted(data.events.filter(r=>r.date>=start&&r.date<=end)),trips=data.trips.filter(r=>r.date>=start&&r.date<=end),breaks=data.yearEvents.filter(r=>r.date<=end&&r.end>=start);return `<div class="section-bar">${button('events','Add family event')}${button('trips','Add trip')}${button('yearEvents','Add break')}</div><div class="two-col">${card('Family dates this month',events.length?rows('events',events,r=>`<strong>${esc(r.title)}</strong>${pill(r.kind)}<small>${dateLabel(r.date)} · ${esc(student(r.studentId))}</small>${r.note?`<p>${esc(r.note)}</p>`:''}`):empty('events'))}${card('Learning beyond home',rows('trips',sorted(trips),r=>`<strong>${esc(r.title)}</strong><small>${dateLabel(r.date)} · ${esc(r.place||'Destination')}</small>`))}${card('Breaks & holidays',rows('yearEvents',breaks,r=>`<strong>${esc(r.title)}</strong>${pill(r.kind)}<small>${dateLabel(r.date)} – ${dateLabel(r.end)}</small>`),'full')}</div>${card('Daily rhythm',`<div class="section-bar">${button('routines','Add routine')}${button('checkins','Log how today felt')}</div>${rows('routines',data.routines,r=>`<strong>${esc(r.title)}</strong>${pill(r.frequency)}<small>${esc(student(r.studentId))} · ${esc(r.time||'Any time')}${r.frequency==='Weekly'?' · '+esc(r.day):''}</small>${r.note?`<p>${esc(r.note)}</p>`:''}`)}`,'full')}${card('Family check-ins',rows('checkins',sorted(data.checkins).reverse(),r=>`<strong>${esc(r.feeling)}</strong><small>${dateLabel(r.date)} · ${esc(student(r.studentId))}</small>${r.note?`<p>${esc(r.note)}</p>`:''}`),'full')}<p class="help">Use Calendar for the dated month grid. Family events and check-ins stay on this device; this is not a shared or synced calendar.</p>`}
function yearView(){return `<div class="section-bar">${button('yearEvents','Add break, term or holiday')}<button class="button secondary" data-view="settings">Edit year dates & targets</button></div><div class="stats two"><div class="stat"><small>School year</small><strong>${dateLabel(data.settings.yearStart)}</strong><span>to ${dateLabel(data.settings.yearEnd)}</span></div><div class="stat"><small>Year targets</small><strong>${data.settings.targetDays} days</strong><span>${data.settings.targetHours} hours</span></div></div>${card('Terms, holidays & breaks',rows('yearEvents',sorted(data.yearEvents),r=>`<strong>${esc(r.title)}</strong>${pill(r.kind)}<small>${dateLabel(r.date)} – ${dateLabel(r.end)}</small>${r.note?`<p>${esc(r.note)}</p>`:''}`))}<p class="help">Set the school year in Customize. Add your own breaks and holidays; no jurisdiction schedule is preloaded.</p>`}
function assessmentView(){const a=sorted(filtered(data.assessments)).reverse(),graded=a.filter(r=>r.score!=null);return `<div class="section-bar">${selectStudents()}${button('assessments','Add assessment')}</div><div class="stats two"><div class="stat"><small>Assessments logged</small><strong>${a.length}</strong></div><div class="stat"><small>With a score</small><strong>${graded.length}</strong><span>Included in Gradebook</span></div></div>${card('Quizzes, tests & standardized results',rows('assessments',a,r=>`<strong>${esc(r.title)}</strong>${pill(r.kind)}<small>${dateLabel(r.date)} · ${esc(student(r.studentId))} · ${esc(subject(r.subjectId))}</small>${r.score!=null?`<span class="grade-chip">${r.score}/${r.maxScore} · ${Math.round(r.score/r.maxScore*100)}%</span>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}`))}<p class="help">A standardized result is recorded exactly as entered. The gradebook uses only assessments with earned and possible points.</p>`}
function assignments(){const a=sorted(filtered(data.lessons).filter(r=>['Assignment','Project'].includes(r.type))),late=a.filter(r=>r.status!=='Done'&&r.date<today());return `<div class="section-bar">${selectStudents()}<button class="button primary" data-add="lessons" data-add-type="Assignment">+ Add assignment</button></div><div class="stats two"><div class="stat"><small>Open assignments</small><strong>${a.filter(r=>r.status!=='Done').length}</strong></div><div class="stat"><small>Past due</small><strong>${late.length}</strong><span>Based on the due date you entered</span></div></div>${card('Due dates & priorities',rows('lessons',a,r=>`<strong>${esc(r.title)}</strong>${pill(r.priority||'Normal')}${r.status!=='Done'&&r.date<today()?pill('Past due','late'):''}<small>${dateLabel(r.date)} · ${esc(student(r.studentId))} · ${esc(subject(r.subjectId))} · ${esc(r.status)}</small>${r.objective?`<p>${esc(r.objective)}</p>`:''}`))}<p class="help">Choose Assignment or Project in the lesson form. Past due labels appear in the app; there are no push notifications.</p>`}
function projectsView(){return `<div class="section-bar">${selectStudents()}${button('projects','Add project')}${button('projectSteps','Add milestone')}${button('achievements','Record achievement')}</div><div class="two-col">${card('Project-based learning',rows('projects',filtered(data.projects),r=>`<strong>${esc(r.title)}</strong>${pill(r.status)}<small>${esc(student(r.studentId))} · ${dateLabel(r.date)}${r.due?' – '+dateLabel(r.due):''}</small>${progress(data.projectSteps.some(x=>x.projectId===r.id)?data.projectSteps.filter(x=>x.projectId===r.id&&x.status==='Done').length:r.progress,data.projectSteps.some(x=>x.projectId===r.id)?data.projectSteps.filter(x=>x.projectId===r.id).length:r.target)}<small>${data.projectSteps.some(x=>x.projectId===r.id)?data.projectSteps.filter(x=>x.projectId===r.id&&x.status==='Done').length+'/'+data.projectSteps.filter(x=>x.projectId===r.id).length:r.progress+'/'+r.target} milestones</small>${r.research?`<p><strong>Research:</strong> ${esc(r.research)}</p>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}`))}${card('Project milestones',rows('projectSteps',sorted(data.projectSteps),r=>`<strong>${esc(r.title)}</strong>${pill(r.status)}<small>${esc(data.projects.find(p=>p.id===r.projectId)?.title||'Project')} · ${r.due?dateLabel(r.due):'No due date'}</small>${r.research?`<p>${esc(r.research)}</p>`:''}`))}${card('Awards & achievements',rows('achievements',sorted(filtered(data.achievements)).reverse(),r=>`<span class="award-badge" aria-hidden="true">★</span><strong>${esc(r.title)}</strong>${pill(r.kind)}<small>${dateLabel(r.date)} · ${esc(student(r.studentId))}</small><p>${esc(r.description||'')}</p>`))}</div>`}
function compliance(){const days=schoolDays(),hours=schoolHours(),daily=sum(data.attendance.filter(r=>r.date===today()&&r.status==='Present'),'minutes')/60,weekly=sum(data.attendance.filter(r=>r.date>=weekStart(today())&&r.date<=addDays(weekStart(today()),6)&&r.status==='Present'),'minutes')/60;return `<div class="section-bar">${button('requirements','Add local requirement')}<button class="button secondary" data-view="settings">Edit planning targets</button></div><div class="stats"><div class="stat"><small>Hours today</small><strong>${daily.toFixed(1)}</strong><span>Across students logged</span></div><div class="stat"><small>Days this school year</small><strong>${days}</strong><span>of ${data.settings.targetDays} target</span></div><div class="stat"><small>Hours this week</small><strong>${weekly.toFixed(1)}</strong><span>Across students logged</span></div><div class="stat"><small>Hours this school year</small><strong>${hours.toFixed(1)}</strong><span>of ${data.settings.targetHours} target</span></div></div>${card('Your planning targets',`${valueBar('Attendance dates',days,data.settings.targetDays)}${valueBar('Instructional hours',hours.toFixed(1),data.settings.targetHours)}<p class="help">Totals across students count each attendance entry’s minutes; per-student totals are in Reports.</p>`)}${card('Locally defined recordkeeping checklist',rows('requirements',data.requirements,r=>`<strong>${esc(r.title)}</strong>${pill(r.category)}${pill(r.status)}${r.target?`${progress(r.progress||0,r.target)}<small>${r.progress||0}/${r.target} recorded</small>`:''}${r.source?`<p>Source / notes: ${esc(r.source)}</p>`:''}`))}<p class="help">This is a manual organizer, not a state-law database or automated compliance determination. Enter rules from your own authority and verify records independently.</p>`}

