const headings={dashboard:['A little more room to learn','See what is next, without losing the bigger picture.'],planner:['Lessons for real life','Plan once, then add scores to the same lesson.'],calendar:['Your learning month','Lessons and attendance in one dated view.'],students:['Every learner is different','Keep profiles and subjects close at hand.'],attendance:['Every learning day counts','Log attendance and instructional time.'],gradebook:['Grades with less double work','Scores entered on lessons and assessments appear here automatically.'],progress:['Each learner at a glance','Subject progress, attendance and goals in clear charts.'],curriculum:['Know what is in progress','Courses, costs and units completed.'],reading:['Stories worth remembering','Books, minutes and reflections.'],goals:['Small steps, meaningful growth','Follow each student’s learning goals.'],enrichment:['Learning beyond the desk','Trips, activities and a portfolio index.'],family:['The family calendar','Appointments, trips and breaks in one place.'],year:['Your school year','Plan terms, holidays and personal targets.'],assessments:['Assessments in context','Quiz, test and standardized results.'],assignments:['Assignments in view','Due dates, priorities and completion.'],projects:['Learning by doing','Projects, milestones and achievements.'],compliance:['Your records, organized','Monitor personal targets and review local requirements.'],budget:['A clear view of learning costs','Curriculum, trips and purchases together.'],reports:['Tell the learning story','Printable, student-specific summaries.'],library:['Keep useful ideas nearby','Notes and web resources in one place.'],settings:['Make it your homeschool','Comfort, targets, grades and backups.']};
function searchResults(){const q=search.trim().toLocaleLowerCase(),matches=[];for(const k of kinds)for(const r of data[k])if(Object.values(r).some(v=>typeof v==='string'&&v.toLocaleLowerCase().includes(q)))matches.push({k,r});return `<section class="card"><h2>Search results · ${matches.length}</h2>${matches.slice(0,100).map(({k,r})=>`<article class="record"><div class="record-body"><strong>${esc(r.title||r.name||labels[k])}</strong><small>${esc(labels[k])} ${r.date?'· '+dateLabel(r.date):''}</small></div>${actions(k,r)}</article>`).join('')||'<p>No matching records.</p>'}${matches.length>100?'<p>Showing the first 100 results. Refine your search.</p>':''}</section>`}
function render(){const h=headings[view],main=$('#main');main.innerHTML=`<div class="global-search"><label for="globalSearch">Search your homeschool</label><input type="search" id="globalSearch" value="${esc(search)}" placeholder="Search lessons, students, books, notes…"><button class="button secondary" data-print>Print</button></div>${search.trim()?searchResults():title(...h)+page[view]()}`;document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false')})}
function formOpen(k,rid='',date=''){if(!fields[k])return;const old=data[k].find(r=>r.id===rid)||{};modal={k,rid};$('#dialogTitle').textContent=(rid?'Edit ':'Add ')+labels[k];$('#formFields').innerHTML=fields[k].map(([key,label,type,required])=>{let value=old[key];if(value==null)value=type==='date'?date||today():type==='color'?'#74a898':type==='score'?'':type==='money'||type==='int'?0:'';if(type==='money'&&old[key]!=null)value=(old[key]/100).toFixed(2);let control;if(type==='textarea')control=`<textarea name="${key}" maxlength="3000">${esc(value)}</textarea>`;else if(type==='student'||type==='subject'||type==='project')control=`<select name="${key}" ${required?'required':''}><option value="">${required?'Choose one':'None'}</option>${data[type==='student'?'students':type==='project'?'projects':'subjects'].map(r=>`<option value="${esc(r.id)}" ${value===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`;else if(type.startsWith('select:'))control=`<select name="${key}">${type.slice(7).split('|').map(v=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`;else control=`<input name="${key}" type="${['money','int','score'].includes(type)?'number':type==='url'?'url':type}" ${type==='money'?'min="0" step="0.01"':type==='int'||type==='score'?'min="0" step="1"':''} ${required?'required':''} ${['text','url'].includes(type)?'maxlength="3000"':''} value="${esc(value)}">`;return `<label class="field">${label}${control}</label>`}).join('');if(k==='portfolio')$('#formFields').insertAdjacentHTML('beforeend',`<label class="field">Attach image or PDF (up to 2 MB)<input name="attachmentFile" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"></label>${old.attachmentName?`<p class="help">Current file: ${esc(old.attachmentName)}. Choose another to replace it.</p>`:''}`);previousFocus=document.activeElement;dialog.showModal();$('#formFields').querySelector('input,select,textarea')?.focus()}
