$('#mobileSections').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close-menu')){$('#mobileSections').close();return}if(b.dataset.view){view=b.dataset.view;search='';menuFocus=null;$('#mobileSections').close();render();window.scrollTo(0,0);$('#main').focus()}});$('#mobileSections').addEventListener('close',()=>{const target=menuFocus;menuFocus=null;if(target?.isConnected)target.focus()});
