$('#recordForm').addEventListener('submit',async e=>{e.preventDefault();if(!modal)return;const{k,rid}=modal,old=data[k].find(r=>r.id===rid),r={id:rid||uid()};for(const[key,label,type,required]of fields[k]){let v=e.currentTarget.elements[key].value.trim();if(required&&!v)return alert('Please fill in '+label+'.');if(type==='date'&&v&&!dateOK(v))return alert('Enter a valid calendar date.');if(type==='url'&&!validURL(v))return alert('Use a valid http or https link.');if(type==='money'){v=moneyCents(v||'0');if(!Number.isSafeInteger(v)||v<0||v>100000000000)return alert('Enter a valid amount.')}if(type==='int'||type==='score'){v=type==='score'&&!v?null:Number(v||0);if(v!=null&&(!Number.isSafeInteger(v)||v<0||v>100000000000))return alert('Enter a valid whole number.')}r[key]=v}
 if(k==='portfolio'){if(old?.attachmentData){r.attachmentData=old.attachmentData;r.attachmentName=old.attachmentName}const file=e.currentTarget.elements.attachmentFile.files[0];if(file){if(file.size>2_000_000||!['image/png','image/jpeg','image/webp','application/pdf'].includes(file.type))return alert('Choose a PNG, JPEG, WebP, or PDF under 2 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));r.attachmentData='data:'+file.type+';base64,'+btoa(binary);r.attachmentName=file.name.slice(0,150)}}
 if(['lessons','assessments'].includes(k)&&((r.score==null)!==(r.maxScore==null)||r.score!=null&&(r.maxScore<1||r.score>r.maxScore)))return alert('Enter both score and possible points, with earned points no greater than possible.');if(k==='curricula'&&r.unitsDone>r.unitsTotal)return alert('Completed units cannot exceed total units.');if(['goals','projects'].includes(k)&&r.progress>r.target)return alert('Progress cannot exceed the target.');if(k==='reading'&&r.rating>5)return alert('Ratings must be 1 to 5.');if(k==='yearEvents'&&r.end<r.date)return alert('End date cannot precede start date.');if(k==='attendance'&&data.attendance.some(x=>x.id!==rid&&x.studentId===r.studentId&&x.date===r.date))return alert('Attendance already exists for this student and date. Edit that entry instead.');if(!valid({...data,[k]:rid?data[k].map(x=>x.id===rid?r:x):[...data[k],r]}))return alert('Check the form values. No changes were made.');if(rid)data[k][data[k].findIndex(x=>x.id===rid)]=r;else data[k].push(r);dialog.close();save();render()});
function download(name,content,mime='application/json'){const u=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
function csvCell(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function exportCSV(){const cols=['Date','Student','Subject','Title','Type','Status','Priority','Minutes','Category','Score','Possible'],lines=[cols,...data.lessons.map(r=>[r.date,student(r.studentId),subject(r.subjectId),r.title,r.type,r.status,r.priority||'Normal',r.minutes,r.category,r.score??'',r.maxScore??''])];download('open-meadow-lessons.csv',lines.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv')}
function shiftMonth(n){const[y,m,d]=selected.split('-').map(Number),first=dateFrom(y,m-1+n,1),[yy,mm]=first.split('-').map(Number),last=new Date(Date.UTC(yy,mm,0)).getUTCDate();selected=dateFrom(yy,mm-1,Math.min(d,last));render()}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-more')){menuFocus=document.activeElement;const menu=$('#mobileSections');menu.showModal();menu.querySelector('button[data-view]')?.focus();return}if(b.dataset.view){view=b.dataset.view;search='';render();window.scrollTo(0,0);return}if(b.dataset.add){formOpen(b.dataset.add,'',b.dataset.date||'');if(b.dataset.addType)$('#recordForm [name="type"]').value=b.dataset.addType;if(b.dataset.addStudent)$('#recordForm [name="studentId"]').value=b.dataset.addStudent;return}if(b.dataset.edit){const[k,id]=b.dataset.edit.split(':');formOpen(k,id);return}if(b.dataset.delete){const[k,id]=b.dataset.delete.split(':');if(k==='projects'&&data.projectSteps.some(r=>r.projectId===id)){alert('Remove linked milestones before deleting this project.');return}if(k==='students'&&kinds.some(x=>x!=='students'&&data[x].some(r=>r.studentId===id))||k==='subjects'&&kinds.some(x=>x!=='subjects'&&data[x].some(r=>r.subjectId===id))){alert('This record is used elsewhere. Reassign or remove linked entries first.');return}if(confirm('Delete this '+labels[k]+'?')){data[k]=data[k].filter(r=>r.id!==id);save();render()}return}if(b.dataset.date){selected=b.dataset.date;view='planner';planMode='day';render();return}if(b.dataset.shift){const n=Number(b.dataset.shift);if(planMode==='month')shiftMonth(n);else{selected=addDays(selected,n);render()}return}if(b.dataset.month){shiftMonth(Number(b.dataset.month));return}if(b.dataset.mode){planMode=b.dataset.mode;render();return}if(b.dataset.reportMode){reportMode=b.dataset.reportMode;render();return}if(b.hasAttribute('data-today')){selected=today();render();return}if(b.dataset.theme){data.settings.theme=b.dataset.theme;apply();save();render();return}if(b.hasAttribute('data-reset-appearance')){const p=defaults();for(const k of ['theme','customColor','font','density','cards','contrast'])data.settings[k]=p[k];apply();save();render();return}if(b.hasAttribute('data-save-weights')){const x=Object.fromEntries(['Practice','Quiz','Test'].map(k=>[k,Number($(`[data-weight="${k}"]`).value)]));if(Object.values(x).some(v=>!Number.isSafeInteger(v)||v<0||v>100)||Object.values(x).reduce((a,v)=>a+v,0)!==100){alert('Grade weights must be whole numbers adding to 100%.');return}data.settings.weights=x;save();render();return}if(b.hasAttribute('data-print')){window.print();return}if(b.hasAttribute('data-backup')){download('open-meadow-backup-'+today()+'.json',JSON.stringify(data,null,2));return}if(b.hasAttribute('data-import')){$('#backupInput').click();return}if(b.hasAttribute('data-export-csv')){exportCSV();return}if(b.hasAttribute('data-clear')&&confirm('Delete ALL homeschool records from this browser? Download a backup first if needed.')){data=blank();filterStudent='';reportStudent='';save();apply();render();return}if(b.hasAttribute('data-reset-demo')&&confirm('Replace demo edits with the original sample records?')){data=sample();save();apply();render()}});
app.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-filter-student]')){filterStudent=t.value;render();return}if(t.matches('[data-report-student]')){reportStudent=t.value;render();return}if(!t.dataset.setting)return;const k=t.dataset.setting;let v=t.value;if(['targetDays','targetHours'].includes(k)){v=Number(v);if(!Number.isSafeInteger(v)||v<0||v>(k==='targetDays'?3660:100000)){alert('Enter a valid target.');render();return}}if(k==='schoolName')v=v.trim().slice(0,70)||'Our homeschool';if(['yearStart','yearEnd'].includes(k)&&(!dateOK(v)||k==='yearStart'&&v>data.settings.yearEnd||k==='yearEnd'&&v<data.settings.yearStart)){alert('Enter a valid school year range.');render();return}data.settings[k]=v;if(k==='customColor')data.settings.theme='custom';apply();save();render()});
let searchTimer;app.addEventListener('input',e=>{if(e.target.id!=='globalSearch')return;search=e.target.value;const caret=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const q=$('#globalSearch');q.focus();q.setSelectionRange(caret,caret)},150)});
$('#backupInput').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>100_000_000)throw Error('Backup file is too large.');const parsed=upgrade(JSON.parse(await file.text()));if(!valid(parsed))throw Error('This is not a valid Open Meadow backup.');if(!confirm('Replace all current records and settings with this backup?'))return;const old=data;data=parsed;try{await save()}catch(err){data=old;throw err}filterStudent='';reportStudent='';apply();render();alert('Backup restored.')}catch(err){alert('Import failed: '+err.message)}});
if(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname))navigator.serviceWorker?.register('./service-worker.js').catch(()=>{});
initialize();
